update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/hydraulique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance hydraulique","mecanisme":"Nous remettons de la mesure là où il n''y en a plus : température, pression, état du fluide, temps de cycle. Puis nous traitons la cause de la fuite au lieu de l''essuyer.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 80","libelle":"clients réguliers, la plupart arrivés par une panne"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Tout le monde essuie la flaque sous la presse. Personne ne traite ce qui la produit.","puces":[{"accroche":"Personne ne surveille l''hydraulique.","texte":"Aucune analyse de fluide, aucun relevé de température, aucun historique. On attend la casse, elle arrive."},{"accroche":"La pression baisse, la pièce sort hors tolérance.","texte":"L''équipement travaille encore, mais plus à la bonne force. Le rebut monte avant l''arrêt."},{"accroche":"Le flexible haute pression qui cède","texte":"est d''abord un accident évité de justesse. Vieillissement, frottement, montage en contrainte : trois causes connues, jamais contrôlées."},{"accroche":"Le composant neuf monté sur un défaut non traité","texte":"ne tient pas la saison. La facture double, le problème reste."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Une pression stable du premier au dernier cycle","texte":"pompes, limiteurs, accumulateurs, réglages de chaque circuit."},"benefice":"La cadence tient et la pièce reste dans la tolérance, cycle après cycle."},{"prestation":{"accroche":"Les fuites arrêtées à la source","texte":"flexible, raccord, joint, tige marquée, portée reprise."},"benefice":"Fin du fluide perdu, du sol glissant et du risque d''accident au poste."},{"prestation":{"accroche":"Le fluide sous surveillance","texte":"analyse d''huile, mesure de pollution, dépollution, filtre, niveau, température."},"benefice":"Les joints et les distributeurs cessent de mourir en silence."},{"prestation":{"accroche":"Les vérins remis en course","texte":"expertise, dépose, remise en état ou échange, essais."},"benefice":"Le mouvement redevient franc, le broutage disparaît."},{"prestation":{"accroche":"Les centrales et groupes repris","texte":"bâche, refroidissement, échangeur, moteur d''entraînement, crépine."},"benefice":"La cavitation s''arrête avant d''avoir tué la pompe."},{"prestation":{"texte":"**Le schéma relevé quand le dossier d''origine a disparu.**"},"benefice":"Le document utile existe enfin le jour de l''arrêt."},{"prestation":{"accroche":"La panne mixte traitée en une visite","texte":"hydraulique, mécanique, électricité, automatisme sur le même intervenant ou la même équipe."},"benefice":"Un seul déplacement quand le défaut traverse plusieurs technologies."}],"prose":[{"texte":"Vos circuits lâchent plusieurs fois par an ? Le [contrat de maintenance Zéro arrêt](/offres/zero-arret/) coûte moins cher que la troisième intervention. Une fuite en cours se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]}]'::jsonb) where path = '/expertises/hydraulique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"circuit, symptôme, pression relevée, bruit, depuis quand. Quatre champs, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure","texte":"le circuit est qualifié avec vous avant tout déplacement, et le bon profil est arrêté au téléphone."},{"titre":"Le niveau se vérifie avant d''accuser la pompe.","texte":"Le diagnostic commence toujours par le contrôle le plus simple, sans exception."},{"titre":"L''intervention se fait énergie consignée","texte":"purge de la pression résiduelle, calage des charges. Une installation haute pression ne se démonte pas à chaud."},{"titre":"La cause racine est cherchée avant le remplacement.","texte":"Pollution, température, réglage, contrainte de montage : le composant n''est souvent que la victime."},{"titre":"Vous recevez un compte rendu","texte":"situation constatée, travaux réalisés, pièce remplacée, mesures relevées, action recommandée. C''est votre mémoire quand l''équipe change."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Un technicien évalué en entretien technique et comportemental","texte":", 10 % des candidats retenus, dont les habilitations et les autorisations exigées par votre plan de prévention sont vérifiées avant l''arrivée."},{"accroche":"Aucune vente de composants, aucun catalogue à écouler.","texte":"Quand une pièce doit partir au banc d''essai chez un spécialiste, nous le disons et nous organisons la dépose. Un banc est une étape de contrôle, pas un argument commercial."}]},{"type":"cta","question":"Besoin de savoir pourquoi votre presse perd sa pression, avant qu''elle ne casse ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Dépannage de presses hydrauliques et mécaniques sur site, pièces de précision","texte":"un technicien intégré à temps plein, presses et centres d''usinage pris en charge sur place, depuis 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Maintenance préventive et curative d''une fonderie","texte":"site tenu 7 jours sur 7 depuis octobre 2023, avec les équipes techniques internes","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Contrat de maintenance préventive annuelle, logistique","texte":"six techniciens polyvalents en permanence sur les sites de Lyon, hydraulique comprise dans le périmètre couvert, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintien opérationnel d''équipements de tri et de packaging, logistique et transport","texte":"deux techniciens en poste, mécanique, électricité, hydraulique et pneumatique couvertes en propre","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Montages et déplacements de machines, étanchéité et isolation","texte":"lignes et sous-ensembles assemblés, profils réunis selon le chantier, sur 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"}]}]'::jsonb) where path = '/expertises/hydraulique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Combien coûte une intervention hydraulique ?","reponse":"Le chiffrage dépend du circuit, du composant en cause et du niveau d''urgence. Tout est établi sur devis, déplacement annoncé avant l''intervention. Le diagnostic à distance qui précède le déplacement, lui, ne se facture pas."},{"question":"Nous avons déjà un contrat ailleurs. Comment on bascule ?","reponse":"Nous préparons la reprise pendant le préavis de votre contrat en cours : inventaire des groupes et des points de mesure, récupération des historiques, reprise du calendrier de visites. Aucun trou de couverture."},{"question":"Qui répond de la sécurité sur un circuit haute pression ?","reponse":"Nos techniciens. Consignation des énergies, purge de la pression résiduelle, calage des charges, plan de prévention signé, balisage. Vos procédures et vos créneaux d''accès priment sur nos habitudes."},{"question":"Qui intervient sur nos centrales ?","reponse":"Des techniciens salariés de Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. L''hydraulique proportionnelle et son pilotage par automate évoluent vite : la compétence est entretenue, pas déclarée."},{"question":"Travaillez-vous l''hydraulique des engins de chantier ?","reponse":"Non. Notre terrain est l''hydraulique industrielle fixe : presse, injection, levage d''atelier, machine de production. Un engin, une nacelle ou du matériel agricole relève d''un spécialiste du matériel roulant."},{"question":"Couvrez-vous notre région, et les petits sites ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France partout en France. Une seule centrale critique justifie un suivi réel, dimensionné sur votre réalité."}]},{"type":"ctaFinal","question":"Besoin d''arrêter de payer deux fois le même vérin ?","bouton":"Demander une intervention"}]'::jsonb) where path = '/expertises/hydraulique/';
